// PROTECTED: independently AI-reviewed draft. Never import into public practice.
// Human instructional/regulatory review and all approval gates remain outstanding.
export const FINAL_04_06 = [
  {"id":"LOC-F-T04-01","tests":"T04U1","unitCode":"T04U1","module":"module-04","prompt":"For this exercise, an access instrument permits pedestrian passage on weekdays and expressly excludes vehicles. A purchaser’s plan requires delivery trucks on Saturdays. Which comparison is accurate before seeking any additional rights?","choices":["The stated instrument does not grant either the vehicle use or the Saturday use needed by that plan.","Pedestrian passage necessarily includes delivery trucks serving the same destination.","Permission on weekdays necessarily includes weekend access whenever the buyer owns the benefited land.","The instrument grants the intended use because both activities can be called access."],"correctChoice":0,"rationale":"The task compares two explicit scope limitations with the intended use. It does not ask the agent to interpret an ambiguous easement or decide whether another legal right exists.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 6; supplied access-instrument terms","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 6; supplied access-instrument terms"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T04U1-Q’s easement-versus-fee classification. Replacement applies two stated limits to a distinct use proposal.","instructionEvidence":"module-04 T04U1; T04U4, obtain actual scope instruments"},
  {"id":"LOC-F-T04-02","tests":"T04U3","unitCode":"T04U3","module":"module-04","prompt":"A properly prepared inter vivos deed creates a freehold estate whose possession commences on a stated future date. An observer says only a will can create a freehold estate commencing in the future. Which Texas provision addresses that claim?","choices":["Property Code §5.041 permits creation by deed or conveyance of a freehold estate commencing in the future.","Section 5.041 requires every future estate to be created only at the grantor’s death by will.","Any future commencement automatically turns a freehold into a month-to-month tenancy.","The future date means the instrument cannot identify a present future interest at all."],"correctChoice":0,"rationale":"Section 5.041 expressly permits the future-commencing freehold to be created by deed or conveyance in the same manner as by will. Other validity and delivery requirements are not decided by this single point.","source":"Texas Property Code Chapter 5","section":"§5.041","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.041"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original restates the worked life-estate/remainder ladder. New question tests the instrument capable of creating a future estate, not the name of the retained estate.","instructionEvidence":"module-04 T04U3, future estates by ordinary deed"},
  {"id":"LOC-F-T04-03","tests":"T04U2","unitCode":"T04U2","module":"module-04","prompt":"A government seeks land for a qualifying public use and invokes eminent domain. Which issue is central under the Texas constitutional taking provision?","choices":["The constitutional requirements governing taking and compensation.","A public-use assertion alone eliminates every compensation requirement.","The private purchase price offered by the government conclusively establishes constitutionally adequate compensation.","The owner’s refusal of an offer itself completes the government’s acquisition of title."],"correctChoice":0,"rationale":"Article I, § 17 supplies the constitutional framework. Public purpose does not make compensation and lawful process irrelevant, and the broker is not the adjudicator.","source":"Texas Constitution Article I","section":"Article I, § 17","sources":[{"url":"https://tcss.legis.texas.gov/resources/CN/htm/CN.1.htm","reference":"Texas Constitution Article I, Article I, § 17"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain constitutional-taking framework; alternatives now confuse distinct acquisition stages and compensation rather than unrelated option fees. Formative identifies the constitutional source; final asks what remains necessary despite public use.","instructionEvidence":"module-04 T04U2, acquisition and public purpose"},
  {"id":"LOC-F-T04-04","tests":"T04U4","unitCode":"T04U4","module":"module-04","prompt":"A property has a mortgage lien, a restrictive covenant, and an encroaching fence. Which review approach best preserves their different functions?","choices":["Identify the debt security, use restriction, and physical boundary-related issue separately.","Treat the mortgage payoff as the only issue because every recorded restriction secures repayment.","Assume payoff of the mortgage necessarily removes the covenant and fence issue.","Treat the fence encroachment as merely a contractual lending term with no physical boundary issue."],"correctChoice":0,"rationale":"Different encumbrances require different analysis and possible resolution. A financial payoff does not necessarily resolve a use covenant or physical encroachment.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 6, title and survey review","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 6, title and survey review"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"The three-way debt security/use restriction/physical encroachment classification requires additional distinctions beyond formative lien-versus-easement. Its mortgage-payoff distractor is a realistic cure error.","instructionEvidence":"module-04 T04U4","integrationReview":"Root strengthened retained distractors; same assessment decision and correct answer."},
  {"id":"LOC-F-T04-05","tests":"T04U5","unitCode":"T04U5","module":"module-04","prompt":"An owner has never drilled a well. A prospective buyer says Texas recognizes no ownership interest in groundwater beneath the land until someone pumps it. What does §36.002(a) recognize?","choices":["Groundwater ownership in place as real property, subject to the statute’s qualifications.","Ownership only after the first permitted gallon is produced.","Ownership only if no groundwater conservation district covers the land.","An automatic guarantee that an untested well will produce the buyer’s required volume."],"correctChoice":0,"rationale":"Section 36.002(a) recognizes groundwater ownership in place, and subsection (b) describes the property interest subject to the section. Recognition is neither a production guarantee nor an unlimited withdrawal permission.","source":"Texas Water Code Chapter 36","section":"§36.002(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/WA/htm/WA.36.htm","reference":"Texas Water Code Chapter 36, §36.002(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates T04U5-Q’s ownership-versus-regulation branch. Replacement tests the in-place interest before extraction, not whether a district may regulate pumping.","instructionEvidence":"module-04 T04U5, groundwater as part of the landowner’s property; assigned §36.002"},
  {"id":"LOC-F-T04-06","tests":"T04U6","unitCode":"T04U6","module":"module-04","prompt":"Under the mineral-reservation addendum, the seller elects to waive the seller’s surface-use rights. An existing mineral lessee is not a party to the sale. What limitation must the surface buyer understand?","choices":["The seller’s election does not alter surface rights held by the nonparty mineral lessee.","The seller’s election necessarily waives every mineral owner’s and lessee’s surface rights.","The election cancels the mineral lease while leaving the seller’s surface rights unchanged.","The waiver applies only to the lender and cannot affect the seller’s own surface rights."],"correctChoice":0,"rationale":"Section C distinguishes the seller’s election from surface rights held by other owners or existing mineral lessees who are not parties. A seller cannot use this election to extinguish the nonparty’s rights.","source":"TREC Addendum for Reservation of Oil, Gas, and Other Minerals, 44-3","section":"Section C","sources":[{"url":"https://www.trec.texas.gov/sites/default/files/pdf-forms/44-3.pdf","reference":"TREC Addendum for Reservation of Oil, Gas, and Other Minerals, 44-3, Section C"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Keep the current 44-3 Section C nonparty limitation: the practice concerns seller ownership and unauthorized drafting, not extinguishment of a nonparty lessee’s rights by the seller’s waiver. T04U6 explicitly assigns the relevant current form decision.","instructionEvidence":"module-04 T04U6, Sections B/C/D; Form 44-3 C"},
  {"id":"LOC-F-T04-07","tests":"T04U7","unitCode":"T04U7","module":"module-04","prompt":"Assume a sale is covered by the federal lead disclosure framework. The seller possesses a lead-hazard evaluation report but has never commissioned a new test. Which distinction follows from the required disclosure described in 42 U.S.C. §4852d(a)(1)(B)?","choices":["The available report must be provided; that requirement is not itself a duty to commission a new report.","The seller may withhold an existing report unless the buyer pays for a new inspection first.","A report is required only if the seller originally commissioned it personally.","Not having commissioned a new test removes the duty to disclose known lead information."],"correctChoice":0,"rationale":"The statute identifies known hazards and available evaluation reports. It does not make the existing-report duty conditional on commissioning a new assessment. Coverage is supplied rather than inferred from the year of construction.","source":"42 U.S.C. §4852d","section":"42 U.S.C. §4852d(a)(1)(B), existing available report","sources":[{"url":"https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title42-section4852d&num=0&edition=prelim","reference":"42 U.S.C. §4852d(a)(1)(B)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the formative unresolved-specialist-investigation case. New task separates delivery of existing information from creation of a new report.","instructionEvidence":"module-04 T04U7, records duty is delivery of what exists"},
  {"id":"LOC-F-T04-08","tests":"T04U8","unitCode":"T04U8","module":"module-04","prompt":"A valid purchase-money lien is asserted against a homestead. Which feature of the constitutional framework prevents an automatic no-lien conclusion?","choices":["The homestead provision lists permitted categories of debt, including purchase money, subject to applicable requirements.","Purchase-money debt is excluded from the permitted categories whenever the buyer immediately occupies the property.","The purchase-money category permits any unrelated unsecured debt to become a valid homestead lien by using that label.","Homestead protection and a tax exemption make payment of a purchase-money debt optional."],"correctChoice":0,"rationale":"Article XVI, § 50 includes specified exceptions to forced-sale protection. The actual debt and requirements must be evaluated rather than assuming absolute immunity.","source":"Texas Constitution Article XVI","section":"Article XVI, § 50(a)(1)","sources":[{"url":"https://tcss.legis.texas.gov/resources/CN/htm/CN.16.htm","reference":"Texas Constitution Article XVI, Article XVI, § 50(a)(1)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain the specific purchase-money exception rather than the formative’s assertion of absolute immunity. The supplied valid-lien assumption avoids unproved lien formalities.","instructionEvidence":"module-04 T04U8, permitted categories"},
  {"id":"LOC-F-T04-09","tests":"T04U3","unitCode":"T04U3","module":"module-04","prompt":"An unambiguous deed states that Alex’s possessory estate lasts for Blair’s life. Alex dies while Blair is alive. Which life does the supplied provision expressly use to measure the estate’s duration?","choices":["Blair’s life.","Alex’s life.","Whichever of Alex or Blair dies first.","The combined lives of Alex and Blair until both have died."],"correctChoice":0,"rationale":"The expressly supplied measuring life is Blair’s, not Alex’s. The question identifies the stated ending event without deciding succession to Alex’s interest or other legal consequences.","source":"Texas Property Code Chapter 5","section":"§5.001(a); supplied express duration","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.001(a); supplied express duration"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the life-tenant-promises-a-greater-estate problem by changing the lesser estate to leasehold. New task distinguishes the holder’s life from the expressly named measuring life.","instructionEvidence":"module-04 T04U3, duration measured by a life; how long and what ends it"},
  {"id":"LOC-F-T04-10","tests":"T04U4","unitCode":"T04U4","module":"module-04","prompt":"A hypothetical title commitment lists a mortgage release as an unsatisfied requirement and a recorded covenant as an exception to the proposed coverage. No release has arrived. Which status separates those entries correctly?","choices":["The mortgage-release requirement remains open; listing the covenant as an exception does not satisfy that requirement.","Both entries are satisfied merely because they appear in the commitment.","The covenant must be treated as a payoff balance, while the mortgage release needs no further evidence.","The exception automatically removes the mortgage from the public records."],"correctChoice":0,"rationale":"Requirements and excepted risks have different functions. The stated commitment still requests release evidence for the mortgage; the covenant entry does not produce it.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 6A–B; supplied commitment entries","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 6A–B; supplied commitment entries"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the pool/access-easement lesson that title coverage is not use permission. Replacement distinguishes an unmet release requirement from an excepted nonmonetary burden.","instructionEvidence":"module-04 T04U4; module-09 T09U6 commitment requirements and exceptions"},
  {"id":"LOC-F-T04-11","tests":"T04U7","unitCode":"T04U7","module":"module-04","prompt":"In a covered lead-disclosure sale, the parties mutually select a different inspection period. The seller claims that changing the period also removes the separate pamphlet and known-hazard disclosure duties. Which reading fits §4852d(a)(1)?","choices":["The period agreement concerns the inspection opportunity; the separate information duties remain.","Any mutually selected period eliminates all three duties in subsection (a)(1).","The seller may replace the pamphlet with an oral summary whenever the period is shortened.","Only a period longer than ten days preserves the known-hazard disclosure duty."],"correctChoice":0,"rationale":"Subparagraph (C) permits a mutually agreed different period. The pamphlet and known-hazard/report duties are separately identified in (A) and (B); modifying the inspection period does not erase them.","source":"42 U.S.C. §4852d","section":"42 U.S.C. §4852d(a)(1)(A)–(C)","sources":[{"url":"https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title42-section4852d&num=0&edition=prelim","reference":"42 U.S.C. §4852d(a)(1)(A)–(C)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats disclosure-versus-safety-guarantee practice. New question tests the limited scope of a permitted period agreement.","instructionEvidence":"module-04 T04U7, four precise lead-disclosure points"},
  {"id":"LOC-F-T04-12","tests":"T04U3","unitCode":"T04U3","module":"module-04","prompt":"A tenant entered lawfully. The stated possession right has ended, the landlord has not consented to a new tenancy, and the tenant remains. For the course’s estate classification only, which label fits?","choices":["Tenancy at sufferance.","A new fixed-term tenancy merely from remaining in place.","A periodic tenancy established by an agreed recurring rental period not present in these facts.","A fee estate created when the original lease ended."],"correctChoice":0,"rationale":"The course describes sufferance as lawful entry followed by remaining after the right to possess ends without the owner’s consent. Coinmach distinguishes the holdover classifications by the owner’s consent. This classification does not prescribe eviction procedure or adjudicate a real dispute.","source":"Supreme Court of Texas, Coinmach Corp. v. Aspenwood Apartment Corp.","section":"Coinmach Corp. v. Aspenwood Apartment Corp., No. 11-0213, opinion p. 7, holdover classifications","sources":[{"url":"https://www.txcourts.gov/media/819905/OpinionsFY2014.pdf","reference":"Coinmach Corp. v. Aspenwood Apartment Corp., No. 11-0213, opinion p. 7 (printed compilation 000224), holdover classifications"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T04U1-R/T05U7-Q’s sale-does-not-end-tenancy decision. New case supplies ended rights and no consent, unlike the teaching’s accepted-rent holdover with unresolved classification. The original proposal’s §92.332 merely used the label; the court definition now supplies the precise source.","instructionEvidence":"module-04 T04U3 leasehold categories; module-05 T05U8"},
  {"id":"LOC-F-T05-01","tests":"T05U4","unitCode":"T05U4","module":"module-05","prompt":"An owner orally authorizes marketing, but the broker has no written consent to put a sale sign on the property. Which distinct requirement in §1101.652(b)(18) must be addressed before placing the sign?","choices":["Written consent from the owner or the owner’s authorized agent to place the sign.","Any oral marketing authorization necessarily supplies the statute’s written sign consent.","The broker’s advertising budget substitutes for the owner’s written consent.","Written consent is required only after the first purchase offer arrives."],"correctChoice":0,"rationale":"The sign-placement disciplinary provision expressly requires written consent. This is not the separate question whether general marketing authority includes accepting a buyer’s offer.","source":"Texas Occupations Code Chapter 1101","section":"§1101.652(b)(18)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, §1101.652(b)(18)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original changes marketing authority in T05U4-Q to rent-collection authority but asks the identical authority-to-accept decision. Replacement tests a different regulated act and its written-permission requirement.","instructionEvidence":"module-05 T05U4, authority and specific acts; module-11 authority catalogue"},
  {"id":"LOC-F-T05-02","tests":"T05U5","unitCode":"T05U5","module":"module-05","prompt":"For this exercise, a signed fee agreement expressly states: fee earned when a complete purchase agreement is accepted; payment due only at closing. A purchase agreement has been accepted, but closing has not occurred. Which status follows from these supplied terms alone?","choices":["The specified earning event occurred; the specified payment-due event has not yet occurred.","Neither event can have occurred until payment is received.","Acceptance makes payment due immediately despite the separate due-at-closing term.","The earning event never matters once a payment date is also stated."],"correctChoice":0,"rationale":"Earned and presently payable are different contractual questions. The supplied clauses deliberately separate the triggering events; no universal commission-earning rule is inferred.","source":"Texas Occupations Code Chapter 1101","section":"§1101.806(c); supplied signed fee-agreement terms","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, §1101.806(c); supplied signed fee-agreement terms"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original asks only to read an unmet earning condition. Replacement requires recognizing an already satisfied earning condition alongside a later payment condition, unlike the formative oral-writing or post-expiration claim.","instructionEvidence":"module-05 T05U5, compensation structures and agreed earning conditions"},
  {"id":"LOC-F-T05-03","tests":"T05U6","unitCode":"T05U6","module":"module-05","prompt":"A written buyer agreement limits services to a stated scope and term. The agent proposes additional services after expiration. Which issue requires attention before relying on the old agreement?","choices":["Whether a current compliant agreement covers the proposed services and period.","The old term automatically extends whenever the buyer contacts the agent again.","The seller’s instruction can extend a buyer’s brokerage agreement without the buyer’s agreement.","Delivery of IABS once permits services indefinitely under an expired agreement."],"correctChoice":0,"rationale":"The current statutory framework and actual written scope and term must cover the work. An expired limited agreement should not be treated as unlimited ongoing authorization.","source":"Texas Occupations Code Chapter 1101","section":"§ 1101.563","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, § 1101.563"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain new expiration-stage application of scope and term; formative tests initial agreement and showing-only scope, not reuse after expiration.","instructionEvidence":"module-05 T05U6"},
  {"id":"LOC-F-T05-04","tests":"T05U8","unitCode":"T05U8","module":"module-05","prompt":"A tenancy continues from one rental period to the next without a fixed final date under the applicable arrangement. Which classification best describes that periodic structure?","choices":["Periodic tenancy.","A fixed-term tenancy because each recurring payment has a due date.","A tenancy at sufferance even though continued periods are consensual.","A tenancy at will with no agreed periodic rental structure."],"correctChoice":0,"rationale":"The repeating rental-period structure is distinct from a fixed final term and from ownership estates. Section 91.001 addresses termination of periodic tenancies.","source":"Texas Property Code Chapter 91","section":"§ 91.001","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.91.htm","reference":"Texas Property Code Chapter 91, § 91.001"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain periodic-structure classification with plausible leasehold categories, removing unrelated fee and mortgage answers.","instructionEvidence":"module-05 T05U8"},
  {"id":"LOC-F-T05-05","tests":"T05U9","unitCode":"T05U9","module":"module-05","prompt":"A former residential tenant has not yet given the landlord a written forwarding address. The landlord claims the omission permanently forfeits the tenant’s right to a security-deposit refund. What does §92.107 distinguish?","choices":["The address affects when the landlord’s refund/accounting duty arises, but failure to provide it does not forfeit the tenant’s refund right.","No forwarding address automatically converts all security money into earned rent permanently.","A tenant forfeits the refund right unless an address was written into the original lease.","The address requirement permits deductions for normal wear regardless of the deposit rules."],"correctChoice":0,"rationale":"Section 92.107 distinguishes the written-forwarding-address prerequisite from forfeiture: subsection (b) preserves the tenant’s refund right despite failure to give the address. Other accounting facts still matter.","source":"Texas Property Code Chapter 92","section":"§92.107(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.92.htm","reference":"Texas Property Code Chapter 92, §92.107(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats MC-T05’s deposit-is-not-earned-rent correction. Replacement tests a different timing/nonforfeiture rule.","instructionEvidence":"module-05 T05U11 move-out accounting and §92.107; T05U9 deposit framework"},
  {"id":"LOC-F-T05-06","tests":"T05U10","unitCode":"T05U10","module":"module-05","prompt":"An illustrative lease assigns base rent of $1,700 and a separately stated $230 monthly expense reimbursement. No other charge is due for the period. What is the total contractual payment for that period?","choices":["$1,930.","$1,470.","$2,300.","$1,700."],"correctChoice":0,"rationale":"The stated obligations total $1,700 + $230 = $1,930. This is arithmetic under the supplied lease, not a claim that every gross or net lease has the same allocation.","source":"Texas Real Estate Commission rules","section":"§ 531.4, competent application of the stated lease terms","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, § 531.4, competent application of the stated lease terms"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain addition of base rent and a separately stated reimbursement. The practice calculation uses a percentage-rent breakpoint, not the same operation with renamed numbers. Supplied assumptions avoid a universal net-lease allocation claim.","instructionEvidence":"module-05 T05U10; T05U10-R percentage calculation"},
  {"id":"LOC-F-T05-07","tests":"T05U11","unitCode":"T05U11","module":"module-05","prompt":"A residential tenant abandons in violation of the lease. The signed lease contains an express waiver of the landlord’s duty to mitigate. Which statement does §91.006(b) make about that waiver?","choices":["A lease provision purporting to waive the mitigation right or exempt the landlord from that duty is void.","The waiver is effective whenever it appears in a signed lease.","The waiver becomes effective solely because the tenant returned the keys.","The waiver eliminates mitigation only if the landlord calls the future-rent claim liquidated damages."],"correctChoice":0,"rationale":"Section 91.006(b) specifically makes the described waiver or exemption void. The question tests that nonwaivability, not the amount of loss after a landlord has successfully relet.","source":"Texas Property Code Chapter 91","section":"§91.006(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.91.htm","reference":"Texas Property Code Chapter 91, §91.006(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the taught abandonment/mitigation recognition case. Replacement tests the attempted contractual waiver, a separate statutory condition.","instructionEvidence":"module-05 T05U11, nonwaivable mitigation duty"},
  {"id":"LOC-F-T05-08","tests":"T05U12","unitCode":"T05U12","module":"module-05","prompt":"A hypothetical right of first refusal becomes available only when the owner decides to accept a third party’s qualifying offer and gives the required notice. No qualifying offer or notice exists. The holder says it can force an immediate sale at a price of its own choosing. Which part of the stated arrangement is missing?","choices":["The specified third-party-sale trigger and matching opportunity, rather than an unrestricted purchase election.","Only the holder’s willingness to pay any amount.","Only the owner’s decision to read the holder’s demand.","Nothing; every first-refusal right is an immediate option at a holder-selected price."],"correctChoice":0,"rationale":"The supplied first-refusal terms define a conditional opportunity. They do not give the holder an immediate unrestricted purchase option. The question does not announce a universal first-refusal procedure.","source":"Texas Real Estate Commission rules","section":"§531.4; supplied right-of-first-refusal terms","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §531.4; supplied right-of-first-refusal terms"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T05U12-Q’s option-does-not-transfer-possession result. Replacement compares a separately taught contingent first-refusal mechanism with an immediate purchase demand.","instructionEvidence":"module-05 T05U12, first refusal versus purchase option"},
  {"id":"LOC-F-T05-09","tests":"T05U13","unitCode":"T05U13","module":"module-05","prompt":"Negotiations for a covered executory conveyance were primarily in Spanish. The seller supplies a Spanish contract but only English disclosure notices, annual statements, and a default notice. Which scope of §5.068 is relevant?","choices":["The required language copy extends to all written transaction documents, including the listed notices and annual accounting.","Only the contract must be supplied in the negotiation language.","Only documents created before signing fall within the language requirement.","A bilingual buyer’s oral assurance automatically exempts every later written document."],"correctChoice":0,"rationale":"Section 5.068 expressly includes the contract, disclosures, annual accounting, and required default notice. The duty is not exhausted by translating the original contract alone.","source":"Texas Property Code Chapter 5","section":"§5.068","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.068"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates T05U13-R’s personal-trust-does-not-replace-disclosure case. Replacement tests ongoing document coverage under the taught foreign-language requirement.","instructionEvidence":"module-05 T05U13, contract/language requirements; module-08 T08U5"},
  {"id":"LOC-F-T05-10","tests":"T05U14","unitCode":"T05U14","module":"module-05","prompt":"A tenant exercises an option to purchase under the residential lease arrangement described in § 5.0621. Which change does subsection (b) expressly identify?","choices":["Property Code Chapter 92 no longer applies to that lease after the option is exercised.","Chapter 92 continues unchanged after exercise regardless of the express rule in subsection (b).","Chapter 92 first begins applying only when the option is exercised.","Exercise eliminates the need to examine any executory-conveyance requirements applicable to the purchase arrangement."],"correctChoice":0,"rationale":"Section 5.0621(a) addresses the lease portion of the specified arrangement; subsection (b) states that Chapter 92 no longer applies after exercise. The actual exercise event matters independently of marketing labels and rent-credit assumptions.","source":"Texas Property Code Chapter 5","section":"§ 5.0621(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, § 5.0621(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain after strict review. The actual post-exercise Chapter 92 transition is expressly taught in T05U14 and differs from formative initial classification and uncertain rent-credit questions. Source §5.0621(b) directly supports the answer.","instructionEvidence":"module-05 T05U14, paragraph beginning Property Code §5.0621","integrationReview":"Root strengthened retained distractors; same assessment decision and correct answer."},
  {"id":"LOC-F-T05-11","tests":"T05U3","unitCode":"T05U3","module":"module-05","prompt":"Assume a valid signed termination settlement ends future services, releases Invoice B for $1,200, and expressly preserves only the dispute over Invoice A for $850. Which matter should the closeout record retain as expressly unresolved?","choices":["The $850 Invoice A dispute.","Both invoices, because stopping services can never release an accrued claim.","Only the $1,200 Invoice B claim, because it is larger.","Neither invoice, because the word termination overrides the express reservation."],"correctChoice":0,"rationale":"The answer applies the settlement’s express release and reservation. It does not infer the survival of every accrued claim from termination or treat termination as an all-purpose release.","source":"Texas Business & Commerce Code Chapter 26","section":"§26.01 as applicable; supplied valid written settlement","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.26.htm","reference":"Texas Business & Commerce Code Chapter 26, §26.01 as applicable; supplied valid written settlement"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T05U3-R’s termination-does-not-settle-accrued-fee dispute. Replacement supplies a selective release with an explicit exception and requires identifying which claim remains.","instructionEvidence":"module-05 T05U3, actual termination/release terms"},
  {"id":"LOC-F-T05-12","tests":"T05U2","unitCode":"T05U2","module":"module-05","prompt":"A party makes a factual statement known to be false, then later calls it merely sales enthusiasm. What should the legal analysis examine?","choices":["The actual content, knowledge, context, and applicable claim elements rather than the later label alone.","The later opinion label controls even if the original statement asserted a known false material fact.","A factual statement cannot be analyzed unless it appears in the final deed.","A statement made during negotiation is necessarily exempt if no separate advice fee was charged."],"correctChoice":0,"rationale":"A later characterization does not change the underlying words and facts. Material factual misrepresentation and statutory exceptions require substantive analysis.","source":"Texas Business & Commerce Code Chapter 17","section":"§§ 17.46(b) and 17.49(i)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, §§ 17.46(b) and 17.49(i)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain substance-versus-label analysis, but replace the implausible invoice-as-truth alternative.","instructionEvidence":"module-05 T05U2; module-01 T01U6 §17.49(i)"},
  {"id":"LOC-F-T06-01","tests":"T06U2","unitCode":"T06U2","module":"module-06","prompt":"For this closing arithmetic only, the agreed price is $330,000, financing is $260,000, and the $10,000 earnest deposit will be credited against the buyer’s $70,000 cash portion. Ignoring all other costs and credits, how much additional purchase-price cash remains?","choices":["$60,000.","$70,000.","$80,000.","$320,000."],"correctChoice":0,"rationale":"The cash portion is $330,000 − $260,000 = $70,000. The stated $10,000 deposit credit leaves $60,000 additional price cash; the deposit is not added to the sales price or counted twice.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 3 and 5; supplied deposit-credit assumption","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 3 and 5; supplied deposit-credit assumption"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats module-06’s cash-plus-financing mismatch example. Replacement tests crediting a previously paid deposit within an already reconciled cash portion.","instructionEvidence":"module-06 T06U2, connected price and money entries"},
  {"id":"LOC-F-T06-02","tests":"T06U1","unitCode":"T06U1","module":"module-06","prompt":"A seller signs the exact offered terms but instructs the agent not to communicate acceptance until a later event. Which fact prevents treating the signature date alone as a complete formation chronology?","choices":["The actual communication and the parties’ governing conditions still must be established.","The seller’s signature proves the instructed communication already occurred.","A buyer’s deposit establishes communication even if the acceptance was withheld.","The agent may substitute a customary effective date without determining the stated event and actual communication."],"correctChoice":0,"rationale":"Formation depends on the objective agreement and relevant communication context. A signature date alone does not establish every required event.","source":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352","section":"Opinion pages 7–13","sources":[{"url":"https://www.txcourts.gov/media/1445957/180352.pdf","reference":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352, Opinion pages 7–13"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain withheld communication after an unchanged signature: distinct from the formative changed-terms counteroffer and competing withdrawal chronology.","instructionEvidence":"module-06 T06U1; Chalker formation context"},
  {"id":"LOC-F-T06-03","tests":"T06U3","unitCode":"T06U3","module":"module-06","prompt":"The financing addendum calls for a $300,000 loan at the stated terms. The lender is willing to approve only $285,000, although the buyer’s income review is complete and the offered rate is within the agreed limit. Which unresolved issue is most directly shown?","choices":["Whether the buyer can obtain the financing described in the addendum, given the loan-amount shortfall.","Whether a rate within the limit automatically proves every financing term was met.","Whether completed income review necessarily amends the agreed loan amount.","Whether a smaller loan automatically reduces the seller’s agreed price by $15,000."],"correctChoice":0,"rationale":"An approval must be compared with the described terms; income review and an acceptable rate do not by themselves supply the missing amount. Rights and timely action require the actual addendum and lender evidence.","source":"TREC Third Party Financing Addendum, 40-11","section":"Paragraphs 1 and 2A","sources":[{"url":"https://www.trec.texas.gov/forms/third-party-financing-addendum-0","reference":"TREC Third Party Financing Addendum, 40-11, Paragraphs 1 and 2A"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats document-to-document financing figure reconciliation. Replacement compares an actual lender offer with the stipulated loan terms, not borrower versus property approval.","instructionEvidence":"module-06 T06U3, financing terms and Buyer Approval"},
  {"id":"LOC-F-T06-04","tests":"T06U4","unitCode":"T06U4","module":"module-06","prompt":"The proposed transaction conveys an entire two-dwelling duplex, not a single separately conveyed dwelling. Which dwelling-count criterion does §5.008(a) state for its statutory seller-notice scope?","choices":["Whether the property comprises not more than one dwelling unit, as that subsection specifies.","Whether one property-tax account automatically makes multiple dwellings one dwelling unit for this subsection.","Whether financing rather than cash determines this subsection’s dwelling-count scope.","Whether calling the whole duplex a standard resale replaces the statute’s actual scope."],"correctChoice":0,"rationale":"Section 5.008(a) states a not-more-than-one-dwelling-unit scope. The question confines the inquiry to that statutory criterion and does not eliminate other disclosures, contract duties, or a license holder’s known-information obligations.","source":"Texas Property Code Chapter 5","section":"§5.008(a)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.008(a)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the teaching’s newly known conflicting property information after an earlier disclosure. Replacement tests property-unit scope, not an exempt fiduciary’s independent broker disclosure.","instructionEvidence":"module-06 T06U4, statutory scope"},
  {"id":"LOC-F-T06-05","tests":"T06U5","unitCode":"T06U5","module":"module-06","prompt":"The accepted sale contract calls for a general warranty deed. The proposed closing deed expressly limits warranties to claims arising by, through, or under the seller. Assuming the wording has been accurately identified by title counsel, what must be reconciled?","choices":["The narrower stated warranty scope against the general-warranty conveyance promised in the contract.","Only the price, because warranty scope cannot be part of the promised conveyance.","Nothing, because general and special warranties necessarily cover identical historical periods.","Only the notary certificate, because acknowledgment expands every warranty to a general warranty."],"correctChoice":0,"rationale":"The stipulated deed language narrows the warranty scope; comparison with the promised form of deed remains necessary. This does not decide title quality or ask the agent to draft or interpret a disputed instrument.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 9B(1); Property Code §5.022","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 9B(1); Property Code §5.022"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T06U5-R’s new mineral reservation/lesser estate mismatch. Replacement tests warranty scope with ownership unchanged and counsel’s characterization supplied.","instructionEvidence":"module-06 T06U5; module-09 T09U2 warranty distinctions"},
  {"id":"LOC-F-T06-06","tests":"T06U6","unitCode":"T06U6","module":"module-06","prompt":"A signer uses an authorized electronic process, but a page is changed after that signature without renewed assent. Which question is distinct from whether electronic signatures are recognized?","choices":["Whether the signer agreed to the altered terms.","An authentic signature automatically binds the signer to every later alteration of the same file.","A software audit entry can supply the signer’s assent even if the signer did not approve the changed term.","Recognition of electronic signatures makes agreement to the text irrelevant."],"correctChoice":0,"rationale":"UETA recognition does not establish assent to later alterations. The signed record, changes, and attribution evidence must be examined.","source":"Texas Business & Commerce Code Chapter 322","section":"§§ 322.007 and 322.009","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.322.htm","reference":"Texas Business & Commerce Code Chapter 322, §§ 322.007 and 322.009"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain after-signature alteration: different from formative attribution denial and mismatched separately signed versions.","instructionEvidence":"module-06 T06U6; UETA §§322.007/.009"},
  {"id":"LOC-F-T06-07","tests":"T06U7","unitCode":"T06U7","module":"module-06","prompt":"A service agreement is made today. It requires a full nine-month service term beginning six months from today and cannot be fully performed sooner under its terms. Which §26.01(b)(6) measurement is relevant?","choices":["The time from making the agreement to possible full performance, which here extends beyond one year.","Only the nine-month duration of active services, ignoring the delayed start.","Only whether installments are billed monthly.","The time from the first service invoice, regardless of when the agreement was made."],"correctChoice":0,"rationale":"Subsection (b)(6) measures from the date of making, not from the start of work. The specified delay plus mandatory term prevents full performance within one year on these facts.","source":"Texas Business & Commerce Code Chapter 26","section":"§26.01(b)(6)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.26.htm","reference":"Texas Business & Commerce Code Chapter 26, §26.01(b)(6)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the category’s words in the question and answer. Replacement tests the making-date baseline where the active term is shorter than a year, not a renamed two-year lease.","instructionEvidence":"module-06 T06U7, agreements not performable within one year of making"},
  {"id":"LOC-F-T06-08","tests":"T06U8","unitCode":"T06U8","module":"module-06","prompt":"A party has not performed a task, but the task was expressly conditioned on an event that has not occurred. What must precede a conclusion of breach?","choices":["Analysis of the condition and whether the duty became due under the agreement.","Every unperformed task is an immediate breach even while its express prerequisite remains unmet.","The mere appearance of the task in the contract eliminates its stated condition.","An escrow holder’s preference can replace the specified triggering event."],"correctChoice":0,"rationale":"A performance duty and its condition must be read together. An unperformed act is not automatically overdue merely because it appears somewhere in the agreement.","source":"Supreme Court of Texas, North Shore Energy v. Harkins, No. 14-0552","section":"Opinion pages 5–10, reading the whole agreement","sources":[{"url":"https://www.txcourts.gov/media/1436267/140552.pdf","reference":"Supreme Court of Texas, North Shore Energy v. Harkins, No. 14-0552, Opinion pages 5–10, reading the whole agreement"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain an existing but not-yet-due conditional duty, distinct from the formative inspection recommendation that never created the alleged duty.","instructionEvidence":"module-06 T06U8; module-07 T07U1 condition/covenant"},
  {"id":"LOC-F-T06-09","tests":"T06U9","unitCode":"T06U9","module":"module-06","prompt":"Assume buyer default and a valid seller election under resale paragraph 15 to terminate and receive earnest money as liquidated damages, releasing both parties from the contract. Which reading avoids combining that elected branch with an incompatible demand?","choices":["The stated termination/liquidated-damages branch must not be treated as simultaneously requiring the buyer to complete the same purchase.","The seller may treat the contract as terminated while also claiming that this elected branch itself compels closing.","The escrow holder’s receipt of the election automatically adjudicates every disputed default fact.","The release language applies only to the buyer while every seller performance duty remains unchanged."],"correctChoice":0,"rationale":"Paragraph 15 describes alternative contractual responses. The question supplies a valid election of the termination branch and asks its stated operation, not whether a disputed seller demand establishes entitlement.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 15, buyer default and seller alternatives","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 15, buyer default and seller alternatives"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the assertion-of-default/unguaranteed-remedy practice. Replacement supplies default and a valid election, then distinguishes alternative contractual branches.","instructionEvidence":"module-06 T06U9, remedies from the actual contract"},
  {"id":"LOC-F-T06-10","tests":"T06U2","unitCode":"T06U2","module":"module-06","prompt":"A notice field contains an outdated address from a prior transaction. Which risk is directly created?","choices":["The administrative delivery information may not reflect the parties’ agreed current notice arrangement.","A historical template address necessarily remains the agreed destination in every later transaction.","Notice information affects only marketing and can be omitted from performance review.","The escrow receipt’s address automatically replaces every notice address selected by the parties."],"correctChoice":0,"rationale":"Notice information is a substantive administrative input. It should accurately reflect the actual parties and agreed process rather than a template’s historical defaults.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 21","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 21"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain administrative notice-address defect; repair unrelated zero-price and title-transfer distractors.","instructionEvidence":"module-06 T06U2, party/contact and notice review"},
  {"id":"LOC-F-T06-11","tests":"T06U3","unitCode":"T06U3","module":"module-06","prompt":"The selected Buyer Approval period in paragraph 2A expires without the buyer terminating under that paragraph. Considering paragraph 2A’s own stated consequence, what changes?","choices":["The contract is no longer subject to the buyer obtaining Buyer Approval under paragraph 2A.","The entire contract automatically terminates without a buyer notice.","The seller must return earnest money solely because the period ended.","The period automatically restarts when the lender requests another income document."],"correctChoice":0,"rationale":"Paragraph 2A states the consequence of failing to terminate under that provision. It does not create automatic cancellation, refund, or a renewed period; separate provisions require their own analysis.","source":"TREC Third Party Financing Addendum, 40-11","section":"Paragraph 2A","sources":[{"url":"https://www.trec.texas.gov/forms/third-party-financing-addendum-0","reference":"TREC Third Party Financing Addendum, 40-11, Paragraph 2A"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain after strict scrutiny. T06U3 explicitly teaches paragraph 2A’s expiry-without-termination consequence. It is not the practice branch where the buyer assumes a lender’s extension request changes the deadline.","instructionEvidence":"module-06 T06U3, paragraph beginning Paragraph 2A"},
  {"id":"LOC-F-T06-12","tests":"T06U7","unitCode":"T06U7","module":"module-06","prompt":"An intermediary seeks a commission for arranging an oil-and-gas mining lease, and relies solely on an oral compensation promise. Which specifically identified §26.01 category should the reviewer examine?","choices":["Subsection (b)(7), commissions for the listed mineral-interest transactions.","Only subsection (b)(5), and only if the underlying lease lasts longer than one year.","No listed category because a commission is always outside the statute of frauds.","Only subsection (b)(6), so a promptly earned commission can never require a writing."],"correctChoice":0,"rationale":"Section 26.01(b)(7) expressly lists commissions involving oil or gas mining leases and other stated mineral interests. The writing inquiry is not solely the term of the underlying lease or how quickly the service was performed.","source":"Texas Business & Commerce Code Chapter 26","section":"§26.01(a), (b)(7)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.26.htm","reference":"Texas Business & Commerce Code Chapter 26, §26.01(a), (b)(7)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the formative charged-party/authorized-signer condition from the opposite direction. Replacement identifies a different expressly taught promise category and avoids confusing it with the underlying lease term.","instructionEvidence":"module-06 T06U7, identify the promise and mineral commissions"},
];
